98	  public MercifulJsonConverter(ObjectMapper mapper, boolean shouldSanitize, String invalidCharMask) {
99	    this.mapper = mapper;
100	    this.shouldSanitize = shouldSanitize;
101	    this.invalidCharMask = invalidCharMask;
102	    this.fieldTypeProcessorMap = getFieldTypeProcessors();
103	    this.fieldLogicalTypeProcessorMap = getLogicalFieldTypeProcessors();
