106	  /**
107	   * Converts json to Avro generic record.
108	   * NOTE: if sanitization is needed for avro conversion, the schema input to this method is already sanitized.
109	   *       During the conversion here, we sanitize the fields in the data
110	   *
111	   * @param json Json record
112	   * @param schema Schema
113	   */
114	  public GenericRecord convert(String json, Schema schema) {
115	    try {
116	      Map<String, Object> jsonObjectMap = mapper.readValue(json, Map.class);
117	      return convertJsonToAvro(jsonObjectMap, schema);
118	    } catch (HoodieException | IOException e) {
119	      throw new HoodieJsonToAvroConversionException("failed to convert json to avro", e);
120	    }
121	  }
122	
123	  /**
124	   * Clear between fetches. If the schema changes or if two tables have the same schemaFullName then
125	   * can be issues
126	   */
127	  public static void clearCache(String schemaFullName) {
128	    SANITIZED_FIELD_MAPPINGS.remove(schemaFullName);
129	  }
130	
131	  private GenericRecord convertJsonToAvro(Map<String, Object> inputJson, Schema schema) {
132	    GenericRecord avroRecord = new GenericData.Record(schema);
133	    for (Schema.Field f : schema.getFields()) {
134	      Object val = shouldSanitize ? getFieldFromJson(f, inputJson, schema.getFullName(), invalidCharMask) : inputJson.get(f.name());
135	      if (val != null) {
136	        avroRecord.put(f.pos(), convertJsonField(val, f.name(), f.schema()));
137	      }
138	    }
139	    return avroRecord;
140	  }
141	
142	  protected static Object getFieldFromJson(final Schema.Field fieldSchema, final Map<String, Object> inputJson, final String schemaFullName, final String invalidCharMask) {
143	    Map<String, String> schemaToJsonFieldNames = SANITIZED_FIELD_MAPPINGS.computeIfAbsent(schemaFullName, unused -> new ConcurrentHashMap<>());
144	    if (!schemaToJsonFieldNames.containsKey(fieldSchema.name())) {
145	      // if we don't have field mapping, proactively populate as many as possible based on input json
146	      for (String inputFieldName : inputJson.keySet()) {
147	        // we expect many fields won't need sanitization so check if un-sanitized field name is already present
148	        if (!schemaToJsonFieldNames.containsKey(inputFieldName)) {
149	          String sanitizedJsonFieldName = HoodieAvroUtils.sanitizeName(inputFieldName, invalidCharMask);
150	          schemaToJsonFieldNames.putIfAbsent(sanitizedJsonFieldName, inputFieldName);
151	        }
152	      }
153	    }
154	    Object match = inputJson.get(schemaToJsonFieldNames.getOrDefault(fieldSchema.name(), fieldSchema.name()));
155	    if (match != null) {
156	      return match;
157	    }
158	    // Check if there is an alias match
159	    for (String alias : fieldSchema.aliases()) {
160	      if (inputJson.containsKey(alias)) {
161	        return inputJson.get(alias);
162	      }
163	    }
164	    return null;
165	  }
