167	  private Schema getNonNull(Schema schema) {
168	    List<Schema> types = schema.getTypes();
169	    Schema.Type firstType = types.get(0).getType();
170	    return firstType.equals(Schema.Type.NULL) ? types.get(1) : types.get(0);
171	  }
