    BigDecimal dec = BigDecimal.valueOf(rand.nextDouble())
        .setScale(scale, RoundingMode.HALF_UP).round(new MathContext(precision, RoundingMode.HALF_UP));
    byte[] enc = dec.unscaledValue().toByteArray();
    int size = computeMinBytesForPrecision(precision);
    String s = "{\"type\":\"fixed\",\"name\":\"f\",\"size\":" + size + ",\"logicalType\":\"decimal\",\"precision\":" + precision + ",\"scale\":" + scale + "}";
