    BigDecimal after = new Conversions.DecimalConversion().fromFixed(fixed, fixedSchema, fixedSchema.getLogicalType());
    if (!dec.equals(after)) throw new RuntimeException("convertBytesToFixed mismatch: " + dec + " vs " + after);
