+  /**
+   * Generates a random non-zero {@link BigDecimal} with the provided scale and precision and returns
+   * its unscaled value as a Base64-encoded string.
+   */
+  private static String getNonzeroEncodedBigDecimal(Random rand, int scale, int precision) {
+    double nextDouble = rand.nextDouble();
+    while (nextDouble <= 0.1) {
+      nextDouble = rand.nextDouble();
+    }
+    // Scale the fractional value up so that the integer part occupies at most (precision - scale) digits.
+    double valuescale = Math.pow(10, precision - scale - 1);
+    BigDecimal dec = BigDecimal.valueOf(nextDouble * valuescale)
+        .setScale(scale, RoundingMode.HALF_UP)
+        .round(new MathContext(precision, RoundingMode.HALF_UP));
+    return Base64.getEncoder().encodeToString(dec.unscaledValue().toByteArray());
+  }
